-- ---------------------------------------------------------------------------
-- V1: the schema as the application stands at the end of Phase 8.
--
-- Written from the DDL Hibernate derives from the entity model (exported with
-- the PostgreSQL dialect), not from memory, so the mapping and the migration
-- agree. From here on Hibernate only validates: every later change is a new
-- migration, and this file is never edited once it has run anywhere.
--
-- Conventions carried over from the entities:
--   * UUID primary keys, generated by the application rather than the database
--   * created_at / updated_at / version on every table (BaseEntity)
--   * timestamptz for every instant, because deadlines must not shift with a
--     server's timezone
--   * enums stored as their names in varchar, with a CHECK constraint so a
--     value the application does not recognise cannot be written
-- ---------------------------------------------------------------------------

-- ----------------------------------------------------------------- teams ---
CREATE TABLE teams (
    id          UUID          NOT NULL,
    name        VARCHAR(80)   NOT NULL,
    description VARCHAR(240),
    active      BOOLEAN       NOT NULL,
    created_at  TIMESTAMPTZ   NOT NULL,
    updated_at  TIMESTAMPTZ   NOT NULL,
    version     BIGINT        NOT NULL,
    CONSTRAINT pk_teams PRIMARY KEY (id),
    CONSTRAINT uk_teams_name UNIQUE (name)
);

-- ----------------------------------------------------------------- users ---
-- password_hash holds a BCrypt digest and nothing else; the column is sized for
-- one (60 characters) with room to spare.
CREATE TABLE users (
    id            UUID         NOT NULL,
    email         VARCHAR(160) NOT NULL,
    password_hash VARCHAR(100) NOT NULL,
    name          VARCHAR(120) NOT NULL,
    role          VARCHAR(32)  NOT NULL,
    active        BOOLEAN      NOT NULL,
    team_id       UUID,
    created_at    TIMESTAMPTZ  NOT NULL,
    updated_at    TIMESTAMPTZ  NOT NULL,
    version       BIGINT       NOT NULL,
    CONSTRAINT pk_users PRIMARY KEY (id),
    CONSTRAINT uk_users_email UNIQUE (email),
    CONSTRAINT ck_users_role CHECK (role IN ('EMPLOYEE', 'SUPPORT_AGENT', 'ADMIN')),
    CONSTRAINT fk_users_team FOREIGN KEY (team_id) REFERENCES teams (id)
);

CREATE INDEX ix_users_team ON users (team_id);
CREATE INDEX ix_users_role ON users (role);

-- ---------------------------------------------------------- sla_policies ---
-- Times are positive by constraint, and a response may not be allowed longer
-- than a resolution: the service rejects both, and so does the database, because
-- a rule worth enforcing is worth enforcing where the data lives.
CREATE TABLE sla_policies (
    id                      UUID        NOT NULL,
    name                    VARCHAR(80) NOT NULL,
    priority                VARCHAR(16) NOT NULL,
    response_time_minutes   INTEGER     NOT NULL,
    resolution_time_minutes INTEGER     NOT NULL,
    active                  BOOLEAN     NOT NULL,
    created_at              TIMESTAMPTZ NOT NULL,
    updated_at              TIMESTAMPTZ NOT NULL,
    version                 BIGINT      NOT NULL,
    CONSTRAINT pk_sla_policies PRIMARY KEY (id),
    CONSTRAINT uk_sla_policy_priority_name UNIQUE (priority, name),
    CONSTRAINT ck_sla_policies_priority CHECK (priority IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),
    CONSTRAINT ck_sla_policies_response_positive CHECK (response_time_minutes > 0),
    CONSTRAINT ck_sla_policies_resolution_positive CHECK (resolution_time_minutes > 0),
    CONSTRAINT ck_sla_policies_response_within_resolution
        CHECK (response_time_minutes <= resolution_time_minutes)
);

-- Incident creation asks for "the active policy for this priority" on every
-- insert, which is exactly this index.
CREATE INDEX ix_sla_policies_priority_active ON sla_policies (priority, active);

-- ------------------------------------------------------------- incidents ---
-- reference is the human-facing id (INC-000123); reference_seq is its numeric
-- part, kept so the next one is a max() rather than string parsing.
--
-- The SLA columns are two clocks: a response deadline answered by the first
-- agent action, and a resolution deadline answered by resolving. The *_breached_at
-- markers record that a breach was announced, which is what stops the sweep
-- announcing it again every minute.
CREATE TABLE incidents (
    id                      UUID         NOT NULL,
    reference               VARCHAR(24)  NOT NULL,
    reference_seq           BIGINT       NOT NULL,
    title                   VARCHAR(160) NOT NULL,
    description             TEXT         NOT NULL,
    category                VARCHAR(60)  NOT NULL,
    subcategory             VARCHAR(60),
    priority                VARCHAR(16)  NOT NULL,
    status                  VARCHAR(24)  NOT NULL,
    reporter_id             UUID         NOT NULL,
    assigned_agent_id       UUID,
    assigned_team_id        UUID,
    sla_policy_id           UUID,
    sla_status              VARCHAR(16),
    response_deadline       TIMESTAMPTZ,
    resolution_deadline     TIMESTAMPTZ,
    response_completed_at   TIMESTAMPTZ,
    resolution_completed_at TIMESTAMPTZ,
    response_breached_at    TIMESTAMPTZ,
    resolution_breached_at  TIMESTAMPTZ,
    resolution_summary      TEXT,
    resolved_at             TIMESTAMPTZ,
    closed_at               TIMESTAMPTZ,
    created_at              TIMESTAMPTZ  NOT NULL,
    updated_at              TIMESTAMPTZ  NOT NULL,
    version                 BIGINT       NOT NULL,
    CONSTRAINT pk_incidents PRIMARY KEY (id),
    CONSTRAINT uk_incidents_reference UNIQUE (reference),
    CONSTRAINT ck_incidents_priority CHECK (priority IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),
    CONSTRAINT ck_incidents_status
        CHECK (status IN ('NEW', 'ASSIGNED', 'IN_PROGRESS', 'RESOLVED', 'CLOSED')),
    CONSTRAINT ck_incidents_sla_status
        CHECK (sla_status IS NULL OR sla_status IN ('ON_TRACK', 'AT_RISK', 'BREACHED', 'COMPLETED')),
    CONSTRAINT fk_incidents_reporter   FOREIGN KEY (reporter_id)       REFERENCES users (id),
    CONSTRAINT fk_incidents_agent      FOREIGN KEY (assigned_agent_id) REFERENCES users (id),
    CONSTRAINT fk_incidents_team       FOREIGN KEY (assigned_team_id)  REFERENCES teams (id),
    CONSTRAINT fk_incidents_sla_policy FOREIGN KEY (sla_policy_id)     REFERENCES sla_policies (id)
);

-- The queue filters on status, priority and team; an employee's list filters on
-- reporter; an agent's queue filters on assigned agent. Each of those is a real
-- query, so each gets an index.
CREATE INDEX ix_incidents_status ON incidents (status);
CREATE INDEX ix_incidents_priority ON incidents (priority);
CREATE INDEX ix_incidents_reporter ON incidents (reporter_id);
CREATE INDEX ix_incidents_assignee ON incidents (assigned_agent_id);
CREATE INDEX ix_incidents_team ON incidents (assigned_team_id);
CREATE INDEX ix_incidents_sla_status ON incidents (sla_status);

-- Every list is ordered by created_at DESC and paged, so the index is declared
-- in that direction.
CREATE INDEX ix_incidents_created_at ON incidents (created_at DESC);

-- The SLA sweep looks for open incidents that still have a deadline. Partial
-- indexes, because the rows it never wants - closed, or carrying no SLA - are
-- the ones it would otherwise page through every minute.
CREATE INDEX ix_incidents_response_deadline_open
    ON incidents (response_deadline)
    WHERE status <> 'CLOSED' AND response_deadline IS NOT NULL;

CREATE INDEX ix_incidents_resolution_deadline_open
    ON incidents (resolution_deadline)
    WHERE status <> 'CLOSED' AND resolution_deadline IS NOT NULL;

-- ------------------------------------------------------ incident_comments ---
CREATE TABLE incident_comments (
    id          UUID        NOT NULL,
    incident_id UUID        NOT NULL,
    author_id   UUID        NOT NULL,
    comment     TEXT        NOT NULL,
    internal    BOOLEAN     NOT NULL,
    created_at  TIMESTAMPTZ NOT NULL,
    updated_at  TIMESTAMPTZ NOT NULL,
    version     BIGINT      NOT NULL,
    CONSTRAINT pk_incident_comments PRIMARY KEY (id),
    -- A blank comment is rejected by the API; the database refuses one too.
    CONSTRAINT ck_comments_not_blank CHECK (btrim(comment) <> ''),
    CONSTRAINT fk_comments_incident FOREIGN KEY (incident_id) REFERENCES incidents (id),
    CONSTRAINT fk_comments_author   FOREIGN KEY (author_id)   REFERENCES users (id)
);

-- The thread is always read for one incident, oldest first.
CREATE INDEX ix_comments_incident ON incident_comments (incident_id);
CREATE INDEX ix_comments_incident_created ON incident_comments (incident_id, created_at);

-- ---------------------------------------------------- incident_activities ---
-- Append-only: the entity has no setters and every column is updatable = false.
-- performed_by_id is nullable because the system itself notices SLA states.
CREATE TABLE incident_activities (
    id              UUID         NOT NULL,
    incident_id     UUID         NOT NULL,
    performed_by_id UUID,
    action          VARCHAR(32)  NOT NULL,
    description     VARCHAR(500) NOT NULL,
    old_value       VARCHAR(160),
    new_value       VARCHAR(160),
    created_at      TIMESTAMPTZ  NOT NULL,
    updated_at      TIMESTAMPTZ  NOT NULL,
    version         BIGINT       NOT NULL,
    CONSTRAINT pk_incident_activities PRIMARY KEY (id),
    CONSTRAINT ck_activities_action CHECK (action IN (
        'INCIDENT_CREATED', 'INCIDENT_ASSIGNED', 'INCIDENT_REASSIGNED', 'TEAM_CHANGED',
        'AGENT_CHANGED', 'STATUS_CHANGED', 'PRIORITY_CHANGED', 'INCIDENT_UPDATED',
        'COMMENT_ADDED', 'INCIDENT_RESOLVED', 'INCIDENT_CLOSED', 'INCIDENT_REOPENED',
        'SLA_AT_RISK', 'SLA_BREACHED', 'SLA_COMPLETED')),
    CONSTRAINT fk_activities_incident     FOREIGN KEY (incident_id)     REFERENCES incidents (id),
    CONSTRAINT fk_activities_performed_by FOREIGN KEY (performed_by_id) REFERENCES users (id)
);

-- The timeline is read for one incident, and the API returns it newest first.
CREATE INDEX ix_activities_incident ON incident_activities (incident_id);
CREATE INDEX ix_activities_incident_created ON incident_activities (incident_id, created_at DESC);

-- --------------------------------------------------------- notifications ---
-- read is reserved in several databases, so the column is read_flag.
CREATE TABLE notifications (
    id                  UUID         NOT NULL,
    recipient_id        UUID         NOT NULL,
    type                VARCHAR(32)  NOT NULL,
    title               VARCHAR(160) NOT NULL,
    message             VARCHAR(500) NOT NULL,
    related_incident_id UUID,
    read_flag           BOOLEAN      NOT NULL,
    created_at          TIMESTAMPTZ  NOT NULL,
    updated_at          TIMESTAMPTZ  NOT NULL,
    version             BIGINT       NOT NULL,
    CONSTRAINT pk_notifications PRIMARY KEY (id),
    CONSTRAINT ck_notifications_type CHECK (type IN (
        'INCIDENT_CREATED', 'INCIDENT_ASSIGNED', 'INCIDENT_UPDATED', 'COMMENT_ADDED',
        'SLA_AT_RISK', 'SLA_BREACHED', 'INCIDENT_RESOLVED', 'INCIDENT_CLOSED')),
    CONSTRAINT fk_notifications_recipient FOREIGN KEY (recipient_id)        REFERENCES users (id),
    CONSTRAINT fk_notifications_incident  FOREIGN KEY (related_incident_id) REFERENCES incidents (id)
);

-- Every read is scoped to one recipient, newest first; the badge counts their
-- unread ones, which is the partial index.
CREATE INDEX ix_notifications_recipient ON notifications (recipient_id);
CREATE INDEX ix_notifications_recipient_created ON notifications (recipient_id, created_at DESC);
CREATE INDEX ix_notifications_recipient_unread
    ON notifications (recipient_id)
    WHERE read_flag = FALSE;

-- The duplicate guard asks whether this person already has this type of
-- notification about this incident.
CREATE INDEX ix_notifications_dedupe ON notifications (recipient_id, type, related_incident_id);

-- --------------------------------------------------- admin_audit_entries ---
-- Administrative actions belong to no incident, which is why they are not in
-- incident_activities. Append-only in the same way.
CREATE TABLE admin_audit_entries (
    id              UUID         NOT NULL,
    performed_by_id UUID,
    target_type     VARCHAR(32)  NOT NULL,
    target_name     VARCHAR(160) NOT NULL,
    description     VARCHAR(500) NOT NULL,
    created_at      TIMESTAMPTZ  NOT NULL,
    updated_at      TIMESTAMPTZ  NOT NULL,
    version         BIGINT       NOT NULL,
    CONSTRAINT pk_admin_audit_entries PRIMARY KEY (id),
    CONSTRAINT fk_admin_audit_performed_by FOREIGN KEY (performed_by_id) REFERENCES users (id)
);

-- Read newest first, and only ever in that order.
CREATE INDEX ix_admin_audit_created ON admin_audit_entries (created_at DESC);
